def read_regular(path, cap, *, directory_fd=None, private_mode=False):
    fd = os.open(path, os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK|os.O_CLOEXEC, dir_fd=directory_fd)
    try:
        before = os.fstat(fd)
        if not stat.S_ISREG(before.st_mode) or before.st_uid != os.getuid() or before.st_nlink != 1 or not 0 <= before.st_size <= cap:
            raise ValueError('public_file_ownership_or_cap')
