        current = os.stat(path, dir_fd=directory_fd, follow_symlinks=False)
        fields = lambda s:(s.st_dev,s.st_ino,s.st_size,s.st_mtime_ns)
        if len(raw) != before.st_size or fields(before) != fields(after) or fields(before) != fields(current):
