def source_check(admission, env):
    import hashlib
    if hashlib.sha256(read_regular(Path(__file__),65536)).hexdigest() != admission['collector_sha256']:
        raise ValueError('collector_source_pin')
    helper = R/'.agents/labs/run_kernel_dispatch.py'
    if hashlib.sha256(read_regular(helper,256*1024)).hexdigest() != admission['helper_sha256']:
        raise ValueError('helper_source_pin')
    for argv,expected in [(['git','rev-parse','HEAD'],admission['source_head']),
                          (['git','status','--porcelain=v1'],''),
                          (['git','show','-s','--format=%G?',admission['source_head']],'G')]:
        if bounded_gateway_get(argv,env).decode('ascii').strip() != expected:
            raise ValueError('source_signed_clean_pin')
    bounded_gateway_get(['git','merge-base','--is-ancestor',PRODUCT_HEAD,admission['source_head']],env)
    raw = read_regular(FREEZE,256*1024)
    if hashlib.sha256(raw).hexdigest() != FREEZE_SHA:
        raise ValueError('product_freeze_pin')
    freeze = decode_public(raw,256*1024)
    if freeze['head'] != PRODUCT_HEAD or freeze['count'] != 753 or len(freeze['inputs']) != 753:
        raise ValueError('product_freeze_scope')
    for name,pin in freeze['inputs'].items():
        if type(name) is not str or name.startswith('/') or '..' in name.split('/'):
            raise ValueError('product_source_path')
        data = read_regular(R/name,1024*1024)
        if len(data) != pin['bytes'] or hashlib.sha256(data).hexdigest() != pin['sha256']:
            raise ValueError('product_source_changed')


def open_owned_directory(path, *, directory_fd=None):
    fd = os.open(path,os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW|os.O_CLOEXEC,dir_fd=directory_fd)
    try:
        info = os.fstat(fd)
        if info.st_uid != os.getuid() or stat.S_IMODE(info.st_mode) != 0o700:
            raise ValueError('owned_directory_scope')
        return fd
    except BaseException:
        os.close(fd)
        raise


def write_exclusive(directory_fd,name,value):
    data = (json.dumps(value,sort_keys=True,separators=(',',':'))+'\n').encode('ascii')
    if len(data) > 16384:
        raise ValueError('public_proof_cap')
    fd = os.open(name,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW|os.O_CLOEXEC,0o600,dir_fd=directory_fd)
    try:
        pending = memoryview(data)
        while pending:
            size = os.write(fd,pending)
            if size <= 0:
                raise OSError('public_proof_short_write')
            pending = pending[size:]
        os.fsync(fd)
    finally:
        os.close(fd)
    os.fsync(directory_fd)


def main():
    import hashlib
    parser = argparse.ArgumentParser()
    parser.add_argument('phase',nargs='?',default='describe',choices=('describe','before','after'))
