    try:
        lab = open_owned_directory(LAB)
        evidence = open_owned_directory('evidence',directory_fd=lab)
        marker = decode_public(read_regular(MARKER,65536,directory_fd=lab),65536)
        if type(marker) is not dict or marker.get('purpose') != 'disposable internal run-kernel acceptance':
            raise ValueError('fixture_marker_scope')
        for key in ('source_head','helper_sha256','run_id','project_id'):
            if marker.get(key) != admission[key]:
                raise ValueError('fixture_marker_identity')
        original_raw = read_regular('run-kernel-original.json',16384,directory_fd=evidence)
        if hashlib.sha256(original_raw).hexdigest() != admission['original_receipt_sha256']:
            raise ValueError('original_creation_receipt_pin')
        original = decode_public(original_raw,16384)
        original_at = checked_event(original,admission,'original-created')
        ready = decode_public(read_regular('run-kernel-stopped-ready.json',16384,directory_fd=evidence),16384)
        ready_at = checked_event(ready,admission,'stopped-ready')
        if not original_at <= ready_at:
            raise ValueError('original_ready_chronology')
        previous = ready_at
        if args.phase == 'after':
            done = decode_public(read_regular('run-kernel-stopped-reads-done.json',16384,directory_fd=evidence),16384)
            previous = checked_event(done,admission,'stopped-reads-done')
            before = decode_public(read_regular('run-kernel-stopped-before.json',16384,directory_fd=evidence),16384)
            if type(before) is not dict or set(before) != {'version','source_head','helper_sha256','run_id','project_id','phase','observed_at','sandboxes'}:
                raise ValueError('before_proof_shape')
            if type(before['version']) is not int or before['version'] != 1 or before['phase'] != 'before':
                raise ValueError('before_proof_kind')
            for key in ('source_head','helper_sha256','run_id','project_id'):
                if before[key] != admission[key]:
                    raise ValueError('before_proof_scope')
            expected = admission['original']
            if before['sandboxes'] != [{**expected,'phase':'Stopped'}]:
                raise ValueError('before_proof_original_VM')
            if not ready_at <= timestamp(before['observed_at']) <= timestamp(done['first_read_at']) <= timestamp(done['last_read_at']) <= previous:
                raise ValueError('before_read_done_chronology')
        now = stamp()
        if not datetime.timedelta(seconds=-2) <= now-previous <= datetime.timedelta(seconds=120):
            raise ValueError('stage_not_fresh')
        name = 'run-kernel-stopped-'+args.phase+'.json'
        try:
            os.stat(name,dir_fd=evidence,follow_symlinks=False)
        except FileNotFoundError:
            pass
        else:
            raise ValueError('existing_original_proof_requires_reconciliation')
        # Sole read-only VM query; scope/source/freshness were checked before it.
        expected = admission['original']
        result = capture_stopped([str(CLI),'sandbox','get',expected['name'],'-o','json'],env,
                                 environment_id=expected['environment_id'],sandbox=expected['name'],sandbox_id=expected['id'])
        if not previous <= timestamp(result['started_at']) <= timestamp(result['observed_at']):
            raise ValueError('capture_stage_chronology')
        source_check(admission,env)
        current = os.stat(LAB,follow_symlinks=False)
        held = os.fstat(lab)
        if (current.st_dev,current.st_ino) != (held.st_dev,held.st_ino):
            raise ValueError('lab_directory_changed')
        current = os.stat('evidence',dir_fd=lab,follow_symlinks=False)
        held = os.fstat(evidence)
        if (current.st_dev,current.st_ino) != (held.st_dev,held.st_ino):
            raise ValueError('evidence_directory_changed')
        proof = {'version':1,'source_head':admission['source_head'],'helper_sha256':admission['helper_sha256'],
                 'run_id':admission['run_id'],'project_id':'lab33','phase':args.phase,
                 'observed_at':result['observed_at'],'sandboxes':[result['sandbox']]}
        write_exclusive(evidence,name,proof)
        print(json.dumps({'phase':args.phase,'original_VMStopped':True,'observed_at':result['observed_at'],
                          'raw_gateway_exported_or_hashed':False}))
    finally:
        if evidence is not None:
            os.close(evidence)
        if lab is not None:
            os.close(lab)


