def unique_pairs(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError('duplicate_gateway_key')
        result[key] = value
    return result


def project_stopped(raw, *, environment_id, sandbox, sandbox_id):
    """Project only the exact original VM's fixed safe fields, never raw metadata."""
    if type(raw) is not bytes or not 0 < len(raw) <= 1024 * 1024:
        raise ValueError('gateway_bytes_limit')
    if type(environment_id) is not str or re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9._-]{0,127}', environment_id) is None:
        raise ValueError('invalid_original_environment')
