                       parse_constant=lambda _: (_ for _ in ()).throw(ValueError('nonfinite_gateway_JSON')))
    if type(value) is not dict:
        raise ValueError('invalid_gateway_object')
    observed = tuple(value.get(key) for key in ('name', 'id', 'phase'))
    if any(type(item) is not str for item in observed) or observed != (sandbox, sandbox_id, 'Stopped'):
        raise ValueError('original_VM_not_proved_stopped')
    return dict(environment_id=environment_id, name=sandbox, id=sandbox_id, phase='Stopped')


