class OwnerTests(unittest.IsolatedAsyncioTestCase):
    def make_owner(self,fail=None,block=None):
        owner=ns['Owner']();calls=[]
        async def runner():
            calls.append('runner')
            if fail=='runner':raise ValueError('synthetic private text must not escape')
        async def provisioner():
            calls.append('provisioner')
            if fail=='provisioner':raise ValueError('synthetic')
        async def manager():
            calls.append('manager')
            if block is not None:await block.wait()
            if fail=='manager':raise ValueError('synthetic')
        def close(name):return lambda:calls.append(name)
        owner.runner=SimpleNamespace(cleanup=runner)
        owner.provisioner=SimpleNamespace(close=provisioner,permissions=SimpleNamespace(close=close('permissions')))
        owner.manager=SimpleNamespace(close=manager)
        owner.store=SimpleNamespace(close=close('store'))
        owner.documents=SimpleNamespace(close=close('documents'))
        owner.shared=SimpleNamespace(records=SimpleNamespace(close=close('shared')))
        owner.environments=SimpleNamespace(close=close('environments'))
        return owner,calls
    async def test_successful_close(self):
        owner,calls=self.make_owner();await owner.close()
        self.assertTrue(owner.closed);self.assertEqual(calls,['runner','provisioner','manager','permissions','store','documents','shared','environments'])
    async def test_each_owner_failure_keeps_stores(self):
        for which in ('runner','provisioner','manager'):
            owner,calls=self.make_owner(fail=which)
            with self.subTest(which=which),self.assertRaises(RefusalError):await owner.close()
            self.assertEqual(calls,['runner','provisioner','manager']);self.assertFalse(owner.closed)
            self.assertEqual(owner.cleanup['failed_owners'],[which])
    async def test_repeated_cancel_drains_before_stores(self):
        release=asyncio.Event();owner,calls=self.make_owner(block=release)
        task=asyncio.create_task(owner.close())
        for _ in range(10):
            if 'manager' in calls:break
            await asyncio.sleep(0)
        task.cancel('first');await asyncio.sleep(0);task.cancel('second');await asyncio.sleep(0)
        self.assertFalse(task.done());self.assertNotIn('store',calls)
        release.set()
        with self.assertRaises(asyncio.CancelledError) as caught:await task
        self.assertEqual(caught.exception.args,('first',));self.assertTrue(owner.closed);self.assertIn('store',calls)
    async def test_cancel_and_failure_preserves_original(self):
        release=asyncio.Event();owner,calls=self.make_owner(fail='manager',block=release)
        task=asyncio.create_task(owner.close())
        for _ in range(10):
            if 'manager' in calls:break
            await asyncio.sleep(0)
        task.cancel('first');await asyncio.sleep(0);release.set()
        with self.assertRaises(asyncio.CancelledError) as caught:await task
        self.assertEqual(caught.exception.args,('first',));self.assertNotIn('store',calls)


