class CompositionGuards(unittest.TestCase):
    def function(self,cls,name):
        node=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name==cls)
        return next(n for n in node.body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)) and n.name==name)
    def test_no_top_level_application_import(self):
        imports=[n for n in tree.body if isinstance(n,ast.ImportFrom)]
        self.assertFalse(any(n.module and n.module.startswith('sandbox_science') for n in imports))
    def test_no_listener_or_model_dispatch(self):
        calls=[n for n in ast.walk(tree) if isinstance(n,ast.Call)]
        names=[n.func.attr for n in calls if isinstance(n.func,ast.Attribute)]
        self.assertNotIn('TCPSite',names);self.assertNotIn('complete',names)
        self.assertNotIn('RunKernelDispatcher',[n.func.id for n in calls if isinstance(n.func,ast.Name)])
    def test_reopen_require_precedes_initialization(self):
        node=self.function('Owner','open')
        condition=next(n for n in node.body if isinstance(n,ast.If) and isinstance(n.test,ast.Name) and n.test.id=='reopened')
        calls=[n for n in ast.walk(condition) if isinstance(n,ast.Call)]
        self.assertEqual(calls[0].func.id,'require_reopen')
        self.assertEqual(calls[1].func.attr,'initialize')
    def test_fixed_cell_count(self):
        node=self.function('Driver','run')
        calls=[n for n in ast.walk(node) if isinstance(n,ast.Call) and isinstance(n.func,ast.Attribute) and n.func.attr=='cell']
        self.assertEqual(len(calls),19)
        self.assertEqual(len({n.args[0].value for n in calls}),19)
    def test_stopped_no_owner_start_close_or_constructor(self):
        node=self.function('Driver','stopped')
        names=[n.func.attr for n in ast.walk(node) if isinstance(n,ast.Call) and isinstance(n.func,ast.Attribute)]
        self.assertNotIn('open',names);self.assertNotIn('start',names);self.assertNotIn('close',names)
    def test_explicit_runtime_flag(self):
        node=next(n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name=='main')
        text=ast.unparse(node)
        self.assertIn('not args.admit',text)
        self.assertIn("args.stage == 'describe'",text)

