            self.assertEqual(calls,['runner','provisioner','manager']);self.assertFalse(owner.closed)
            self.assertEqual(owner.cleanup['failed_owners'],[which])
    async def test_repeated_cancel_drains_before_stores(self):
        release=asyncio.Event();owner,calls=self.make_owner(block=release)
        task=asyncio.create_task(owner.close())
        for _ in range(10):
            if 'manager' in calls:break
            await asyncio.sleep(0)
        task.cancel('first');await asyncio.sleep(0);task.cancel('second');await asyncio.sleep(0)
        self.assertFalse(task.done());self.assertNotIn('store',calls)
        release.set()
        with self.assertRaises(asyncio.CancelledError) as caught:await task
        self.assertEqual(caught.exception.args,('first',));self.assertTrue(owner.closed);self.assertIn('store',calls)
    async def test_cancel_and_failure_preserves_original(self):
        release=asyncio.Event();owner,calls=self.make_owner(fail='manager',block=release)
        task=asyncio.create_task(owner.close())
