        while offset < len(raw):
            written = os.write(fd, raw[offset:])
            if written <= 0:
                raise Refusal("evidence write did not progress")
            offset += written
        os.fsync(fd)
        os.fsync(root)
    finally:
        if fd is not None:
            os.close(fd)
        os.close(root)


def git(*args: str) -> str:
    process = subprocess.Popen(["git", *args], cwd=SOURCE, stdin=subprocess.DEVNULL,
                               stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
    data = bytearray()
    deadline = time.monotonic() + 10
    try:
        assert process.stdout is not None
        while True:
            left = deadline - time.monotonic()
            if left <= 0:
                raise Refusal("source guard deadline")
            ready, _, _ = select.select([process.stdout], [], [], min(left, 0.2))
            if not ready:
                continue
            chunk = os.read(process.stdout.fileno(), 4096)
            if not chunk:
                break
            data.extend(chunk)
            if len(data) > 65536:
                raise Refusal("source guard output cap")
        if process.wait(timeout=max(0.01,deadline-time.monotonic())) != 0:
            raise Refusal("source guard failed")
        return data.decode("ascii").strip()
    finally:
        if process.poll() is None:
            process.kill()
        process.wait()
        if process.stdout is not None:
            process.stdout.close()


def source_guard(head: str) -> dict[str, object]:
    if not ADMISSION_READY:
        raise Refusal("helper admission is disabled")
    if type(head) is not str or re.fullmatch(r"[0-9a-f]{40}",head) is None:
        raise Refusal("source pin differs")
    if git("rev-parse","HEAD") != head or git("status","--porcelain") or git("log","-1","--format=%G?") != "G":
        raise Refusal("source is not exact signed clean head")
    pins = {}
    if not INPUTS:
        raise Refusal("source inputs are not pinned")
    for name, expected in INPUTS.items():
        fd = os.open(SOURCE/name,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK|os.O_CLOEXEC)
        try:
            info=os.fstat(fd)
            if not stat.S_ISREG(info.st_mode) or info.st_uid != os.getuid() or not 0<=info.st_size<=1024*1024:
                raise Refusal("source input ownership differs")
            raw=os.pread(fd,1024*1024+1,0)
            after=os.fstat(fd)
            if len(raw)!=info.st_size or (info.st_dev,info.st_ino,info.st_size,info.st_mtime_ns)!=(after.st_dev,after.st_ino,after.st_size,after.st_mtime_ns):
                raise Refusal("source input changed")
            observed=hashlib.sha256(raw).hexdigest()
            if observed != expected:
                raise Refusal("source input pin differs")
            pins[name]={"bytes":len(raw),"sha256":observed}
        finally:
            os.close(fd)
    helper=Path(__file__).read_bytes()
    if len(helper)>256*1024:
        raise Refusal("helper cap differs")
    return {"source_head":head,"helper_sha256":hashlib.sha256(helper).hexdigest(),"inputs":pins}


def marked(head: str) -> dict[str, Any]:
